/**
 * AISettingsCard component for admin AI analysis configuration
 * - Portions generated by AI
 */

import { useState, useEffect, useCallback } from 'react';
import { Bot, Save, RefreshCw, CheckCircle, XCircle, Sparkles } from 'lucide-react';
import apiClient from '@/api/client';
import type { AISettings } from '@/types';
import { formatMarketTime } from '@/utils/marketTime';

interface AISettingsCardProps {
  isReady: boolean;
}

export function AISettingsCard({ isReady }: AISettingsCardProps) {
  const [settings, setSettings] = useState<AISettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  // Form state
  const [aiEnabled, setAiEnabled] = useState(true);
  const [activeProvider, setActiveProvider] = useState<'gemini' | 'groq' | 'openai'>('gemini');
  const [cacheEnabled, setCacheEnabled] = useState(true);
  const [cacheTtlHours, setCacheTtlHours] = useState(24);

  // Load settings
  useEffect(() => {
    if (!isReady) return;

    const loadSettings = async () => {
      setLoading(true);
      setError(null);
      try {
        const data = await apiClient.getAISettings();
        setSettings(data);
        setAiEnabled(data.ai_enabled);
        setActiveProvider(data.active_provider);
        setCacheEnabled(data.cache_enabled);
        setCacheTtlHours(Math.round(data.cache_ttl_seconds / 3600));
      } catch (err: any) {
        console.error('Failed to load AI settings:', err);
        setError('Failed to load AI settings');
      } finally {
        setLoading(false);
      }
    };

    loadSettings();
  }, [isReady]);

  // Save settings
  const handleSave = useCallback(async () => {
    setSaving(true);
    setError(null);
    setSuccess(false);

    try {
      const updated = await apiClient.updateAISettings({
        ai_enabled: aiEnabled,
        active_provider: activeProvider,
        cache_enabled: cacheEnabled,
        cache_ttl_seconds: cacheTtlHours * 3600,
      });
      setSettings(updated);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err: any) {
      console.error('Failed to save AI settings:', err);
      setError(err.response?.data?.detail || 'Failed to save AI settings');
    } finally {
      setSaving(false);
    }
  }, [aiEnabled, activeProvider, cacheEnabled, cacheTtlHours]);

  // Check if form has changes
  const hasChanges =
    settings &&
    (aiEnabled !== settings.ai_enabled ||
      activeProvider !== settings.active_provider ||
      cacheEnabled !== settings.cache_enabled ||
      cacheTtlHours !== Math.round(settings.cache_ttl_seconds / 3600));

  // Get provider display info
  const getProviderInfo = (name: string) => {
    const info: Record<string, { displayName: string; description: string; badge?: string }> = {
      gemini: {
        displayName: 'Google Gemini Flash',
        description: 'Free tier: 15 requests/min, 1M tokens/day',
        badge: 'Free',
      },
      groq: {
        displayName: 'Groq (Llama 3.1 70B)',
        description: 'Free tier: 30 requests/min, fastest inference',
        badge: 'Fast',
      },
      openai: {
        displayName: 'OpenAI GPT-4o-mini',
        description: 'Paid: ~$0.001 per analysis, most reliable',
        badge: 'Paid',
      },
    };
    return info[name] || { displayName: name, description: '' };
  };

  // Check if provider is available
  const isProviderAvailable = (name: string) => {
    return settings?.available_providers.some(p => p.name === name && p.available) ?? false;
  };

  if (loading) {
    return (
      <div className="card">
        <div className="flex items-center gap-2 mb-4">
          <Bot size={20} className="text-primary-400" />
          <h2 className="text-xl font-semibold">AI Analysis</h2>
        </div>
        <div className="flex items-center justify-center py-8 text-gray-400">
          <RefreshCw size={20} className="animate-spin mr-2" />
          Loading...
        </div>
      </div>
    );
  }

  return (
    <div className="card">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Bot size={20} className="text-primary-400" />
          <h2 className="text-xl font-semibold">AI Analysis</h2>
          <Sparkles size={16} className="text-yellow-400" />
        </div>
        {settings?.updated_at && (
          <span className="text-xs text-gray-500">
            Last updated: {formatMarketTime(settings.updated_at)}
          </span>
        )}
      </div>

      {error && (
        <div className="mb-4 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {success && (
        <div className="mb-4 p-3 bg-green-500/10 border border-green-500/30 rounded-lg text-green-400 text-sm">
          AI settings saved successfully!
        </div>
      )}

      <div className="space-y-4">
        {/* Enable/Disable AI Toggle */}
        <div className="p-3 bg-dark-800 rounded-lg">
          <div className="flex items-center justify-between">
            <div>
              <label className="font-medium text-white">Enable AI Analysis</label>
              <p className="text-xs text-gray-500 mt-0.5">
                Allow users to analyze stocks with AI-powered recommendations
              </p>
            </div>
            <button
              onClick={() => setAiEnabled(!aiEnabled)}
              className={`relative w-12 h-6 rounded-full transition-colors ${
                aiEnabled ? 'bg-primary-500' : 'bg-gray-600'
              }`}
            >
              <span
                className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${
                  aiEnabled ? 'left-7' : 'left-1'
                }`}
              />
            </button>
          </div>
        </div>

        {/* Provider Selection */}
        <div className={`space-y-3 ${!aiEnabled ? 'opacity-50 pointer-events-none' : ''}`}>
          <label className="block text-sm font-medium text-white">Select LLM Provider</label>
          
          {['gemini', 'groq', 'openai'].map((providerName) => {
            const info = getProviderInfo(providerName);
            const isAvailable = isProviderAvailable(providerName);
            const isSelected = activeProvider === providerName;

            return (
              <div
                key={providerName}
                onClick={() => isAvailable && setActiveProvider(providerName as any)}
                className={`p-4 rounded-lg border-2 transition-all cursor-pointer ${
                  isSelected
                    ? 'border-primary-500 bg-primary-500/10'
                    : isAvailable
                    ? 'border-white/10 bg-dark-800 hover:border-white/20'
                    : 'border-white/5 bg-dark-800 opacity-50 cursor-not-allowed'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-white">{info.displayName}</span>
                      {info.badge && (
                        <span className={`text-xs px-1.5 py-0.5 rounded ${
                          info.badge === 'Free' ? 'bg-green-500/20 text-green-400' :
                          info.badge === 'Fast' ? 'bg-yellow-500/20 text-yellow-400' :
                          'bg-blue-500/20 text-blue-400'
                        }`}>
                          {info.badge}
                        </span>
                      )}
                      {isAvailable ? (
                        <span className="flex items-center gap-1 text-xs text-green-400">
                          <CheckCircle size={12} />
                          Configured
                        </span>
                      ) : (
                        <span className="flex items-center gap-1 text-xs text-red-400">
                          <XCircle size={12} />
                          No API Key
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-gray-400 mt-1">
                      {info.description}
                    </p>
                  </div>
                  <div
                    className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                      isSelected
                        ? 'border-primary-500 bg-primary-500'
                        : 'border-gray-600'
                    }`}
                  >
                    {isSelected && (
                      <div className="w-2 h-2 rounded-full bg-white" />
                    )}
                  </div>
                </div>
              </div>
            );
          })}

          <p className="text-xs text-gray-500">
            Add API keys in backend/.env file. Fallback order: Gemini → Groq → OpenAI
          </p>
        </div>

        {/* Cache Settings */}
        <div className={`space-y-3 ${!aiEnabled ? 'opacity-50 pointer-events-none' : ''}`}>
          <div className="p-3 bg-dark-800 rounded-lg">
            <div className="flex items-center justify-between">
              <div>
                <label className="font-medium text-white">Cache Analysis Results</label>
                <p className="text-xs text-gray-500 mt-0.5">
                  Store results to avoid repeated LLM calls
                </p>
              </div>
              <button
                onClick={() => setCacheEnabled(!cacheEnabled)}
                className={`relative w-12 h-6 rounded-full transition-colors ${
                  cacheEnabled ? 'bg-primary-500' : 'bg-gray-600'
                }`}
              >
                <span
                  className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${
                    cacheEnabled ? 'left-7' : 'left-1'
                  }`}
                />
              </button>
            </div>
          </div>

          {cacheEnabled && (
            <div className="p-3 bg-dark-800 rounded-lg">
              <label className="block text-sm font-medium text-white mb-2">Cache Duration (hours)</label>
              <input
                type="number"
                value={cacheTtlHours}
                onChange={(e) => setCacheTtlHours(Math.max(1, parseInt(e.target.value) || 1))}
                min={1}
                max={168}
                className="w-full bg-dark-700 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary-500"
              />
              <p className="text-xs text-gray-500 mt-1">
                Recommended: 24 hours. Max: 168 hours (1 week)
              </p>
            </div>
          )}
        </div>

        {/* Save Button */}
        <button
          onClick={handleSave}
          disabled={saving || !hasChanges}
          className={`w-full flex items-center justify-center gap-2 py-2.5 rounded-lg font-medium transition-colors ${
            hasChanges
              ? 'bg-primary-500 hover:bg-primary-600 text-white'
              : 'bg-gray-700 text-gray-400 cursor-not-allowed'
          }`}
        >
          {saving ? (
            <>
              <RefreshCw size={16} className="animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save size={16} />
              Save Changes
            </>
          )}
        </button>
      </div>
    </div>
  );
}
